import { DISCOVERY_SERVICE_URL_VAR, fetchFromDiscovery } from '@/lib/discovery';

/**
 * `GET /.well-known/ucp` — this storefront's UCP business profile.
 *
 * A UCP platform looks for the profile at the apex of the domain a shopper names.
 * The document itself is generated by the Discovery Service, which is deployed
 * elsewhere, so this route fetches it server-side and passes the response through
 * unchanged: same status, same content type, same bytes.
 *
 * It is deliberately a proxy and not a redirect. Some agent fetchers will not
 * follow a cross-origin 3xx on a well-known path, and the failure is silent — the
 * agent simply concludes the merchant has no profile.
 */

export const runtime = 'nodejs';
export const dynamic = 'force-dynamic';

const CORS = {
  // Platforms fetch this from a browser as often as from a server.
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Methods': 'GET, OPTIONS',
  'Access-Control-Allow-Headers': 'Content-Type, UCP-Agent',
};

export async function GET(): Promise<Response> {
  let upstream: Response;
  try {
    upstream = await fetchFromDiscovery('/.well-known/ucp');
  } catch (err) {
    const message = err instanceof Error ? err.message : String(err);
    const configuration = message.startsWith('Missing environment variable');
    console.error('[well-known/ucp]', err);
    return Response.json(
      {
        error: configuration ? 'not_configured' : 'discovery_unreachable',
        message: configuration
          ? message
          : `Could not reach the Discovery Service named by ${DISCOVERY_SERVICE_URL_VAR}.`,
      },
      { status: 502, headers: { ...CORS, 'Cache-Control': 'no-store' } },
    );
  }

  // Pass the upstream response through as-is. Its own status and content type are
  // the answer; rewriting either would hide a Discovery Service fault behind a
  // storefront one, and an agent would have no way to tell the two apart.
  const headers = new Headers(CORS);
  for (const header of ['content-type', 'cache-control', 'etag', 'last-modified']) {
    const value = upstream.headers.get(header);
    if (value) headers.set(header, value);
  }

  return new Response(await upstream.arrayBuffer(), {
    status: upstream.status,
    statusText: upstream.statusText,
    headers,
  });
}

export async function OPTIONS(): Promise<Response> {
  return new Response(null, { status: 204, headers: CORS });
}
